  --danger: #ff6b8a;
  --shadow: 0 0 0 2px var(--line), 6px 6px 0 0 rgba(0,0,0,.45);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(1200px 600px at 50% -10%, #1b2038 0%, transparent 60%),
    var(--bg);
  color: var(--ink);
  font-family: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 15px;
  line-height: 1.5;
}

/* Scanline wash — subtle enough to read through, present enough to feel like a cabinet. */
body::after {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(0deg, rgba(0,0,0,.16) 0 1px, transparent 1px 3px);
  opacity: .5;
  z-index: 100;
}

#app { max-width: 960px; margin: 0 auto; padding: 28px 20px 60px; position: relative; z-index: 1; }

.pixel { font-family: 'Press Start 2P', monospace; line-height: 1.6; }

h1.title {
  font-family: 'Press Start 2P', monospace;
  font-size: 20px;
  margin: 0 0 4px;
  letter-spacing: 1px;
}
.subtitle { color: var(--muted); font-size: 13px; margin-bottom: 26px; }

.topbar { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; flex-wrap: wrap; }

.card {
  background: var(--panel);
