}
.choice .key { font-family: 'Press Start 2P', monospace; font-size: 11px; color: var(--muted); }
.choice.correct { border-color: var(--accent); background: rgba(124,245,200,.12); }
.choice.wrong { border-color: var(--danger); background: rgba(255,107,138,.12); }

.subtopic { text-align: left; width: 100%; display: flex; flex-direction: column; align-items: flex-start; gap: 6px; padding: 16px; }
