func (s *Server) suggestions(ctx context.Context, room *Room) []string {
	if room.Phase != PhaseTopic {
		return nil
	}
	return OfflineTopicSuggestions()
}

func (s *Server) resolveSubTopics(ctx context.Context, room *Room, topic string) []SubTopic {
	if !s.cala.Enabled() {
		return offlineSubTopics(topic)
	}

	ctx, cancel := context.WithTimeout(ctx, 20*time.Second)
	defer cancel()

	entities, err := s.cala.SearchEntities(ctx, topic, 5)
	if err != nil || len(entities) == 0 {
		return offlineSubTopics(topic)
	}
	room.TopicEntity = entities[0].ID

	in, err := s.cala.Introspect(ctx, entities[0].ID)
	if err != nil {
		return offlineSubTopics(topic)
	}
	if subs := SubTopics(in, 5); len(subs) > 0 {
		return subs
	}
	return offlineSubTopics(topic)
}

// startQuiz builds questions off the request path so the picking player is not
// left waiting on Cala; the room polls its way into the quiz phase.
func (s *Server) startQuiz(room *Room) {
	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()

	qs, err := s.buildQuestions(ctx, room)

	room.mu.Lock()
	defer room.mu.Unlock()

	if err != nil || len(qs) == 0 {
		room.Error = "Could not build a round from that topic. Start another game."
		room.Phase = PhaseResults
		return
	}
	room.Questions = qs
	room.QuestionCount = len(qs) // the built count, not the requested one
	room.Current = 0
	room.questionAt = time.Now()
	room.Phase = PhaseQuiz
}

package main

import (
	"fmt"
	"strings"
)

// Numeric axes are phrased from the axis itself rather than through a generic
// "higher X" template. "Which has the higher founded year?" is technically
// correct and reads like a database; "Which was founded first?" reads like a
// quiz. Years also need era handling — a founding date of -218 is 218 BC, not
// minus two hundred and eighteen.

// isYearAxis reports whether an axis holds a calendar year.
func isYearAxis(key string) bool {
	k := strings.ToLower(key)
	return strings.HasSuffix(k, "_year") || k == "year" ||
		strings.Contains(k, "founded") || strings.Contains(k, "launch")
}

// numericPrompt returns the question text and whether the answer is the
// *lower* value. For years the natural question is "which came first", which
// inverts what counts as the winning side.
func numericPrompt(label, key string) (prompt string, lowerWins bool) {
	if isYearAxis(key) {
		switch {
		case strings.Contains(strings.ToLower(key), "launch"):
			return "Which launched first?", true
		case strings.Contains(strings.ToLower(key), "founded"):
			return "Which was founded first?", true
		}
		return fmt.Sprintf("Which has the earlier %s?", strings.ToLower(label)), true
	}
	return fmt.Sprintf("Which has the higher %s?", strings.ToLower(label)), false
}

// formatValue renders a value for the reveal line, with eras on years.
func formatValue(key string, v float64) string {
	if isYearAxis(key) {
		year := int64(v)
		if year < 0 {
			return fmt.Sprintf("%d BC", -year)
		}
		return fmt.Sprintf("%d", year)
	}
	return formatNum(v)
}
// deez.win — a multiplayer quiz where the questions come from a verified
// entity graph rather than from a language model.
//
// The loop: players join a room, dice decide the order, the winner picks an
// overall topic, and everyone else claims one of the top five sub-topics Cala
// actually holds data for. Questions are built from those axes.
package main

import (
	"embed"
	"flag"
	"io/fs"
	"log"
	"net/http"
	"os"
	"time"
)

//go:embed static
