		formatUnit("founding_date", -218, ""):      "218 BC",
		formatUnit("x", 1234.5, "EUR"):             "€1,234.50",
	}
	for got, want := range cases {
		if got != want {
			t.Errorf("got %q want %q", got, want)
		}
	}
}
